import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const read=path=>readFileSync(new URL('../core/'+path,import.meta.url),'utf8');
const {R,F}=new Function(read('finance.js')+'\n'+read('reconciliation.js')+'\nreturn {R:Reconciliation,F:Finance}')();
const row={id:'rent',date:'2026-10-09',category:'Rent',type:'Expense',cents:7500};
const incoming={...row,id:'load',type:'Income',category:'Linehaul',cents:20000};
const line=R.statementLine('2026-10-10','Net settlement','125.00','2026-10');
const draft={opening:0,closing:12500,lines:[line]};
assert.throws(()=>R.close(draft,[row,incoming]));
line.matches=[R.snapshot(row),R.snapshot(incoming)];
assert.equal(R.close(draft,[row,incoming]).closed,true);
assert.throws(()=>R.close({...draft,closing:12499},[row,incoming]));
assert.throws(()=>R.close(draft,[row,{...incoming,cents:19500}]));
assert.throws(()=>R.close(draft,[incoming]));
assert.equal(R.snapshot({...row,type:'Transfer',category:'Unknown'}),null);
assert.equal(R.snapshot(F.reverse(row,row.date,'fix')).cash,7500);
assert.equal(R.signed('-0.01'),-1);
assert.throws(()=>R.statementLine('2026-09-30','Outside','1','2026-10'));
assert.deepEqual([...R.usedIds([draft])],['rent','load']);
assert.equal(R.usedIds([draft],line.id).size,0);
const mixed={...row,type:'Income',splits:[{category:'Labor',classification:'revenue',cents:7000},{category:'Tax',classification:'sales_tax',cents:500}]};
assert.equal(R.snapshot(mixed).cash,7500);assert.equal(F.total([mixed]).income,7000);
console.log('PASS reconciliation, net settlements, changed records, reversals and split sales tax');
